def parse_date(s):
    # Strip the trailing 'Z' (UTC) and any timezone offset so we can parse the date part.
    if s.endswith("Z"):
        s = s[:-1]
    # Handle timezone offset like +00:00
    if len(s) >= 6 and s[-6] in "+-":
        s = s[:-6]
    elif len(s) >= 5 and s[-5] in "+-":
        s = s[:-5]
    return datetime.date.fromisoformat(s[:10])

